/**
 * Day-by-day itineraries of the long tours and the schematic region map.
 *
 * EN and DE day texts are the company's own, word for word from polarhestar.is
 * (read 2026-10-09; the site has no Icelandic pages, so IS is our translation,
 * condensed, written to the same facts). The CMS carries an `itinerary` field;
 * these are the seed and the offline fallback. "Back to the Roots" has no
 * itinerary published, so it has none here either.
 *
 * The map is SCHEMATIC: places are projected from their real latitude and
 * longitude onto one flat frame (no coastline survey), enough to show where a
 * day goes, never a hiking map. Coordinates: viewBox 0 0 1000 700.
 */
import type { L3 } from './schedule'

export interface ItineraryDay {
  n: number
  /** Arrival / departure days carry a title; riding days are just "Day n". */
  kind?: 'arrival' | 'departure'
  body: L3
  /** Map place ids the day touches, in order. */
  places: string[]
}
export interface Itinerary {
  days: ItineraryDay[]
}

export const DAY_TITLE: Record<NonNullable<ItineraryDay['kind']>, L3> = {
  arrival: { is: 'Koma', en: 'Arrival', de: 'Ankunft' },
  departure: { is: 'Brottför', en: 'Departure', de: 'Abreise' },
}

